// Extraer el JSON de la respuesta del agente AI
const input = $input.first().json.output || $input.first().json.response || $input.first().json.text || JSON.stringify($input.first().json);

let cronica;
try {
  // Buscar objeto JSON en la respuesta (puede venir con texto alrededor)
  const match = input.match(/\{[\s\S]*"id"[\s\S]*\}/);
  if (match) {
    cronica = JSON.parse(match[0]);
  } else {
    cronica = JSON.parse(input);
  }
} catch (e) {
  throw new Error('La IA no devolvió un JSON válido. Respuesta: ' + input.substring(0, 500));
}

// Validar campos obligatorios
const camposRequeridos = ['id', 'titulo', 'fecha', 'categoria', 'resumen', 'cuerpo', 'imagen', 'fuente'];
for (const campo of camposRequeridos) {
  if (!cronica[campo]) {
    throw new Error('Falta el campo obligatorio: ' + campo);
  }
}

return [{ json: cronica }];

// Obtener la crónica generada por la IA
const cronica = $('Parsear Crónica JSON').first().json;

// Obtener el contenido actual del archivo desde GitHub
const githubResponse = $('Leer noticias.json').first().json;

let noticias;
if (typeof githubResponse.content === 'string') {
  // Contenido en base64
  noticias = JSON.parse(Buffer.from(githubResponse.content, 'base64').toString('utf-8'));
} else if (githubResponse.content && typeof githubResponse.content === 'object') {
  noticias = githubResponse.content;
} else {
  noticias = [];
}

// Asegurar que es un array
if (!Array.isArray(noticias)) {
  noticias = noticias.noticias || noticias.items || [];
}

// Insertar la nueva crónica al inicio del array
noticias.unshift(cronica);

// Serializar y codificar en base64 para GitHub
const contenidoJSON = JSON.stringify({ noticias }, null, 2);
const contenidoBase64 = Buffer.from(contenidoJSON, 'utf-8').toString('base64');

return [{
  json: {
    sha: githubResponse.sha,
    contenidoBase64: contenidoBase64,
    contenidoJSON: contenidoJSON
  }
}];

